on conflict (profile_id) do update set
  source_id = excluded.source_id,
  dataset_class = excluded.dataset_class,
  country_code = excluded.country_code,
  region_group = excluded.region_group,
  profile_summary = excluded.profile_summary,
  resume_as_of_year = excluded.resume_as_of_year,
  resume_as_of_month = excluded.resume_as_of_month,
  resume_as_of_precision = excluded.resume_as_of_precision,
  review_status = excluded.review_status,
  scope_status = excluded.scope_status,
  synthetic_demo_allowed = excluded.synthetic_demo_allowed,
  scenario_code = excluded.scenario_code,
  test_tags = excluded.test_tags,
  data_quality_flags = excluded.data_quality_flags;

on conflict (profile_id, employer_id) do update set
  industry_raw = excluded.industry_raw,
  industry_sector = excluded.industry_sector,
  company_model = excluded.company_model,
  business_model = excluded.business_model,
  company_size_band = excluded.company_size_band,
  attribute_provenance = excluded.attribute_provenance;

on conflict (employment_id) do update set
  profile_id = excluded.profile_id,
  sequence_index = excluded.sequence_index,
  employer_id = excluded.employer_id,
  title_raw_redacted = excluded.title_raw_redacted,
  role_id = excluded.role_id,
  seniority_code = excluded.seniority_code,
  mapping_status = excluded.mapping_status,
  mapping_confidence = excluded.mapping_confidence,
  mapping_note = excluded.mapping_note,
  employment_type = excluded.employment_type,
  primary_career_sequence = excluded.primary_career_sequence,
  counts_as_full_time_experience = excluded.counts_as_full_time_experience,
  classification_note = excluded.classification_note,
  start_year = excluded.start_year,
  start_month = excluded.start_month,
  start_precision = excluded.start_precision,
  end_year = excluded.end_year,
  end_month = excluded.end_month,
  end_precision = excluded.end_precision,
  is_current_as_stated = excluded.is_current_as_stated,
  extraction_status = excluded.extraction_status,
  data_quality_flags = excluded.data_quality_flags;

on conflict (education_id) do update set
  profile_id = excluded.profile_id,
  qualification_level = excluded.qualification_level,
  field_of_study = excluded.field_of_study,
  study_mode = excluded.study_mode,
  completion_status = excluded.completion_status,
  start_year = excluded.start_year,
  start_month = excluded.start_month,
  start_precision = excluded.start_precision,
  end_year = excluded.end_year,
  end_month = excluded.end_month,
  end_precision = excluded.end_precision;

on conflict (break_id) do update set
  profile_id = excluded.profile_id,
  break_reason = excluded.break_reason,
  note_redacted = excluded.note_redacted,
  start_year = excluded.start_year,
  start_month = excluded.start_month,
  start_precision = excluded.start_precision,
  end_year = excluded.end_year,
  end_month = excluded.end_month,
  end_precision = excluded.end_precision;

on conflict (evidence_id) do update set
  profile_id = excluded.profile_id,
  employment_id = excluded.employment_id,
  evidence_type = excluded.evidence_type,
  responsibility_area = excluded.responsibility_area,
  evidence_text_redacted = excluded.evidence_text_redacted,
  provenance = excluded.provenance,
  evidence_status = excluded.evidence_status,
  confidence = excluded.confidence;

on conflict (profile_skill_id) do update set
  profile_id = excluded.profile_id,
  skill_id = excluded.skill_id,
  skill_text_raw = excluded.skill_text_raw,
  employment_id = excluded.employment_id,
  evidence_id = excluded.evidence_id,
  evidence_source = excluded.evidence_source,
  confidence = excluded.confidence,
  verified = excluded.verified;

-- Approved synthetic fixture resumes: the trace_ingest allowlist (v2.4.0). Each fixture id is
-- paired with the SHA-256 of its PDF in data/synthetic/synthetic_resume_pdfs.zip. Rows of removed fixtures go
-- with their trace_ref.profiles row (ON DELETE CASCADE).
on conflict (fixture_profile_id) do update set
  pdf_sha256 = excluded.pdf_sha256;

commit;
